"""Deterministic compilation of individually authored records. No question multiplication/paraphrase loop.
Every call/row is one authored item; option rotation changes placement only, never creates extra items.
AI-authored originals, not independently human-reviewed. Run from repository root.
"""
import json,re,hashlib
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
PROV={'kind':'original','author':'STUDY 990 / Codex','revision':'bank2026-r8','note':'AI-authored original. Machine consistency checks; not independently human-reviewed or ETS material.','editorialStatus':'ai-draft'}
PACKS={k:{'questions':[],'stimuli':[],'passages':[]} for k in ['mock-listening','mock-reading','practice-listening','practice-reading']}
SEQ={k:0 for k in PACKS}
ACTIVE='mock-listening'
IDS={k:[] for k in PACKS}
GRAM={'word-form':'word-forms','agreement':'agreement','tenses':'tenses','passive':'passive','verb-patterns':'verb-patterns','connectors':'connectors','conditionals':'conditionals','relative-clauses':'relatives','subjunctive':'subjunctive','prepositions':'prepositions','comparisons':'comparisons','modals':'modals'}
def use(pack):
 global ACTIVE
 ACTIVE=pack

def mc(part,prompt,choices,why,skill=None,topic='office',vocab=None,stimulus=None,**extra):
 """Correct choice is authored first; rotate positions to avoid an all-A key. why may include individual choice reasons."""
 SEQ[ACTIVE]+=1; n=SEQ[ACTIVE];qid=f'bank2026-{ACTIVE}:q{n:03}'
 explanations=why if isinstance(why,list) else [why]+[f'Lựa chọn «{x}» không trả lời đúng câu hỏi. {why}' for x in choices[1:]]
 width=len(choices)
 offset=sorted(range(width),key=lambda i:hashlib.sha256(f'{ACTIVE}:{part}:{n//width}:{i}'.encode()).digest())[n%width]
 pairs=list(zip(choices,explanations));pairs=pairs[offset:]+pairs[:offset]
 opts=[{'id':'ABCD'[i],'text':c,'reasoning':r} for i,(c,r) in enumerate(pairs)]
 skill=skill or ({1:'photo-detail',2:'listening-intent',3:'listening-detail',4:'listening-detail',5:'word-form',6:'text-cohesion',7:'reading-detail'}[part])
 q={'schemaVersion':1,'id':qid,'part':part,'prompt':prompt,'options':opts,'answer':next(o['id'] for o in opts if o['text']==choices[0]),'explanation':explanations[0],'takeaway':{'photo-detail':'Chỉ chọn hành động/vị trí nhìn thấy trong ảnh.','listening-intent':'Đáp lại mục đích giao tiếp, không chỉ từ nghe giống.','listening-detail':'Xác định đúng người, thời gian và hành động.','listening-main-idea':'Dựa vào mục đích toàn bài nói.','listening-inference':'Suy luận vừa đủ từ bằng chứng, không thêm giả định.','visual-integration':'Kết hợp điều kiện trong audio với bảng biểu.','reading-detail':'Đối chiếu câu trả lời với bằng chứng trong văn bản.','reading-inference':'Chỉ suy ra điều văn bản hỗ trợ.','cross-text':'Ghép bằng chứng từ các văn bản, không đọc riêng lẻ.','text-cohesion':'Xét quan hệ ý và tham chiếu giữa các câu.'}.get(skill,'Xác định chức năng ngữ pháp của vị trí trống trước khi chọn.'),'skills':[skill],'difficulty':'advanced' if skill in ['cross-text','listening-inference','subjunctive','text-cohesion'] else 'foundation' if skill in ['photo-detail','word-form'] else 'intermediate','grammarIds':[GRAM[skill]] if skill in GRAM else [],'vocabularyIds':vocab or [],'provenance':PROV,'topic':topic,**extra}
 if stimulus:q['stimulusId']=stimulus
 PACKS[ACTIVE]['questions'].append(q);IDS[ACTIVE].append(qid)
 return q

def stim(part,title,body=None,passages=None,exhibit=None):
 s={'id':f'bank2026-{ACTIVE}:s{len(PACKS[ACTIVE]["stimuli"])+1:03}','title':title,'part':part,'topic':'office','provenance':PROV,'kind':{1:'photograph',2:'question-response',3:'conversation',4:'talk',6:'text-completion',7:'reading'}[part]}
 if body:s['audio']={'kind':'synthetic','transcript':body}
 if passages:
  s['passageIds']=[]
  for j,(format,text) in enumerate(passages):
   p={'id':s['id']+f'-doc{j+1}','title':title+f' · Document {j+1}','format':format,'text':text};PACKS[ACTIVE]['passages'].append(p);s['passageIds'].append(p['id'])
 if exhibit:s['exhibit']=exhibit
 PACKS[ACTIVE]['stimuli'].append(s);return s

def qr(prompt,correct,w1,w2,why,topic='office',vocab=None):
 s=stim(2,'Question–Response · '+prompt,prompt);s['topic']=topic
 q=mc(2,'Choose the best response to the spoken question.',[correct,w1,w2],why,topic=topic,vocab=vocab,stimulus=s['id'])
 s['audio']['transcript']=prompt

def group(part,title,body,items,exhibit=None):
 if part==3:body=re.sub(r' (?=[A-Z][a-z]+(?: [A-Za-z]+){0,2}:)', '\n', body)
 s=stim(part,title,body,exhibit=exhibit)
 for row in items:
  prompt,answers,why,*rest=row
  mc(part,prompt,answers,why,skill=rest[0] if rest else None,stimulus=s['id'],vocab=rest[1] if len(rest)>1 else [])

def reading(title,docs,items):
 s=stim(7,title,passages=docs)
 for row in items:
  prompt,answers,why,*rest=row
  mc(7,prompt,answers,why,skill=rest[0] if rest else 'reading-detail',stimulus=s['id'],vocab=rest[1] if len(rest)>1 else [])

def completion(title,text,items):
 s=stim(6,title,passages=[('email',text)])
 for i,(answers,why,skill) in enumerate(items,1):
  mc(6,f'Choose the best completion for blank {{{{{i}}}}} in {title}.',answers,why,skill,stimulus=s['id'],blankKey=str(i),blankType='sentence' if i==4 else 'word',vocab=['notify'] if 'notify' in text.lower() else [])

