# Add only exact lexical references present in the authored context, using a captured local index.
def write_packages():
 index=json.loads((ROOT/'content/reference-index.json').read_text(encoding='utf-8'))
 refs=index['vocabulary']; grammar_ids=index['grammarIds']
 output=ROOT/'content/packages';output.mkdir(exist_ok=True)
 topics=json.loads((ROOT/'content/topic-tags.json').read_text(encoding='utf-8'))
 for name,bank in PACKS.items():
  sby={s['id']:s for s in bank['stimuli']};pby={p['id']:p for p in bank['passages']}
  for stimulus in bank['stimuli']: stimulus['topic']=topics.get(stimulus['title'],stimulus['topic'])
  for q in bank['questions']:
   if q.get('stimulusId') in sby:q['topic']=sby[q['stimulusId']]['topic']
   s=sby.get(q.get('stimulusId'),{})
   context=q['prompt']+' '+next(o['text'] for o in q['options'] if o['id']==q['answer'])+' '+s.get('audio',{}).get('transcript','')+' '+' '.join(pby[i]['text'] for i in s.get('passageIds',[]))
   found=[v['id'] for v in refs if any(re.search(r'(?<![a-z])'+re.escape(f.lower())+r'(?![a-z])',context.lower()) for f in [v['word'],*v['forms']])]
   q['vocabularyIds']=list(dict.fromkeys([*q['vocabularyIds'],*found]))[:6]
  bank['grammarIds']=grammar_ids;bank['vocabularyIds']=[v['id'] for v in refs]
  photo_refs={s['photograph']['src'] for s in bank['stimuli'] if s['kind']=='photograph'}
  media=[{'path':a['src'],**{k:a[k] for k in ['author','sourceUrl','license','licenseUrl']},'sha256':a['sha256']} for a in json.loads((ROOT/'content/photo-assets.json').read_text(encoding='utf-8')) if a['src'] in photo_refs]
  package={'format':'study990.content','formatVersion':2,'id':'bank2026-'+name,'revision':'bank2026-r8','purpose':'mock' if name.startswith('mock') else 'practice','review':{'status':'ai-draft','author':'Codex','date':'2026-10-22','note':'AI-authored, structure and consistency checks only; not independently human-reviewed.'},'bank':bank,'media':media}
  (output/(name+'.json')).write_text(json.dumps(package,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
 counts={k:{str(p):sum(q['part']==p for q in b['questions']) for p in range(1,8)} for k,b in PACKS.items()}
 mock=[q for k,b in PACKS.items() if k.startswith('mock') for q in b['questions']]
 practice=[q for k,b in PACKS.items() if k.startswith('practice') for q in b['questions']]
 print(json.dumps({'byPackage':counts,'mock':len(mock),'practice':len(practice)},indent=2))
 assert [sum(q['part']==p for q in mock) for p in range(1,8)]==[6,25,39,30,30,16,54]
 assert len(practice)==200
 sets=[{'id':'bank2026-mock-01','title':'STUDY 990 · Mock 01','revision':'bank2026-r8','questionIds':[q['id'] for q in sorted(mock,key=lambda q:q['part'])],'durationMinutes':120,'editorialStatus':'ai-draft','note':'200 original items in the paper-test Part distribution. Synthetic speech; 120-minute total practice budget, not official recording timing or an ETS exam.'}]
 (ROOT/'content/mock-exams.json').write_text(json.dumps(sets,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')

if __name__=='__main__':
 revisions=json.loads((ROOT/'content/editorial-revisions.json').read_text(encoding='utf-8'))
 for bank in PACKS.values():
  for q in bank['questions']:
   if q['id'] in revisions:
    old=q['explanation'];q['explanation']=revisions[q['id']]
    for o in q['options']:o['reasoning']=o['reasoning'].replace(old,q['explanation'])
 write_packages()
